<?php require 'config/db.php'; if(!isset($_SESSION['cart']))$_SESSION['cart']=[];
if(isset($_POST['add'])){$id=(int)$_POST['drink_id'];$s=$pdo->prepare('SELECT * FROM drinks WHERE id=? AND is_active=1');$s->execute([$id]);$d=$s->fetch();$qty=max(1,(int)$_POST['qty']);if($d&&$d['stock']>=$qty)$_SESSION['cart'][]=['id'=>$id,'name'=>$d['name'],'price'=>(float)$d['price'],'qty'=>$qty,'size'=>$_POST['size'],'sugar'=>$_POST['sugar'],'ice'=>$_POST['ice']];header('Location: cart.php');exit;}
if(isset($_GET['clear'])){$_SESSION['cart']=[];header('Location: cart.php');exit;}$total=0;foreach($_SESSION['cart'] as $i)$total+=$i['price']*$i['qty'];?>
<!doctype html><html><head><meta charset="utf-8"><title>Cart</title><link rel="stylesheet" href="css/style.css"></head><body><header><nav><a class="logo" href="index.php">🥤 DrinkShop</a><div><a href="menu.php">Menu</a></div></nav></header><main class="container"><h1>Your Cart</h1><?php if(!$_SESSION['cart']):?><p>Cart is empty. <a href="menu.php">Choose a drink</a>.</p><?php else:?><table class="table"><tr><th>Drink</th><th>Options</th><th>Qty</th><th>Subtotal</th></tr><?php foreach($_SESSION['cart'] as $i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['size'])?>, <?=e($i['sugar'])?>, <?=e($i['ice'])?></td><td><?=$i['qty']?></td><td>$<?=number_format($i['price']*$i['qty'],2)?></td></tr><?php endforeach;?></table><h3>Total: $<?=number_format($total,2)?></h3><div class="actions"><a class="btn" href="checkout.php">Checkout</a><a class="btn danger" href="cart.php?clear=1">Clear Cart</a></div><?php endif;?></main></body></html>
